import{At as e,Pt as t,Ut as n,gt as r,ht as i,mt as a,n as o,pt as s,ut as c}from"./chunks/framework.BrKcMR_c.js";var l=JSON.parse(`{"title":"ADR-0030: Corporate default with an unlockable 1337 experience pack","description":"","frontmatter":{},"headers":[],"relativePath":"adrs/0030-corporate-default-and-unlockable-1337-experience.md","filePath":"adrs/0030-corporate-default-and-unlockable-1337-experience.md","lastUpdated":1789092097000}`),u={name:`adrs/0030-corporate-default-and-unlockable-1337-experience.md`};function d(o,l,u,d,f,p){let m=t(`Term`);return e(),s(`div`,null,[l[21]||=a(`<h1 id="adr-0030-corporate-default-with-an-unlockable-1337-experience-pack" tabindex="-1">ADR-0030: Corporate default with an unlockable 1337 experience pack <a class="header-anchor" href="#adr-0030-corporate-default-with-an-unlockable-1337-experience-pack" aria-label="Permalink to “ADR-0030: Corporate default with an unlockable 1337 experience pack”">​</a></h1><p><strong>Status:</strong> Accepted · 2026-09-01 · Refines <a href="/adrs/0011-liquid-glass-and-window-translucency">ADR-0011</a>, <a href="/adrs/0013-themes-as-data">ADR-0013</a>, and <a href="/adrs/0022-theme-format-and-community-themes">ADR-0022</a></p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2>`,3),c(`p`,null,[l[1]||=i(`GOAT's visual work mixed two product identities. The underlying macOS application is a serious local AI workspace, but prominent neon treatments, goat copy, emoji, and mascot motion made the playful `,-1),r(m,{term:`1337`},{default:n(()=>[...l[0]||=[i(`1337`,-1)]]),_:1}),l[2]||=i(` identity look like the default product. That narrows the audience and makes ordinary work feel less calm than the current light and dark icon direction.`,-1)]),c(`p`,null,[l[4]||=i(`The theme system already treats colour `,-1),r(m,{term:`token`},{default:n(()=>[...l[3]||=[i(`tokens`,-1)]]),_:1}),l[5]||=i(` as data and keeps an unlockable 1337 theme. Colour alone is no longer enough to describe the intended easter egg. The complete experience includes alternate app icons, chat decorations, animations, bylines, and selected microcopy. These must remain optional, local, accessible, and unable to change application semantics.`,-1)]),c(`p`,null,[r(m,{term:`kid`},{default:n(()=>[...l[6]||=[i(`Kid`,-1)]]),_:1}),l[7]||=i(` 0.1.0 must ship with the intended identity rather than defer the correction to the later M7 polish release.`,-1)]),l[22]||=a(`<h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><h3 id="professional-by-default" tabindex="-1">Professional by default <a class="header-anchor" href="#professional-by-default" aria-label="Permalink to “Professional by default”">​</a></h3><p>GOAT launches in <strong>System</strong>, following macOS appearance through a restrained corporate Light or Midnight token set. The standard experience uses:</p><ul><li>the current professional light and dark app-icon family;</li><li>SF Pro for application chrome and SF Mono only for code;</li><li>monochrome interface symbols with limited semantic colour;</li><li>conventional labels such as <strong>Generate</strong>, <strong>Negative prompt</strong>, and <strong>Save preset</strong>;</li><li>quiet selection, focus, progress, and streaming treatments; and</li><li>deadpan, actionable copy throughout normal workflows.</li></ul>`,4),c(`p`,null,[l[9]||=i(`Pasture, Light, Midnight, and community `,-1),r(m,{term:`theme`},{default:n(()=>[...l[8]||=[i(`themes`,-1)]]),_:1}),l[10]||=i(` remain available, but they change visual tokens only. System is the first-run default. The 1337 option is absent from Appearance until it is unlocked.`,-1)]),l[23]||=a(`<h3 id="about-owns-the-easter-egg" tabindex="-1">About owns the easter egg <a class="header-anchor" href="#about-owns-the-easter-egg" aria-label="Permalink to “About owns the easter egg”">​</a></h3><p>The command palette is not required to discover or unlock 1337. With the About window frontmost, pressing <strong>Option-Command-G</strong> arms a short local digit capture. Entering <code>1337</code> within ten seconds unlocks the pack. The About view gives no permanent instruction or visible input before the chord.</p><p>Unlocking is idempotent and stored as a local preference. It reveals <strong>GOAT 1337</strong> in Appearance, shows one celebratory confirmation, and selects it for the current user. Afterward it behaves like any other selectable appearance and the user can return to System immediately. No network, account, date, or remote flag participates.</p><p>The exact chord may change before implementation if it conflicts with a macOS reserved command. The invariant is that the unlock is About-scoped, deliberate, keyboard-driven, and does not depend on M7&#39;s command palette.</p><h3 id="_1337-is-a-presentation-pack" tabindex="-1">1337 is a presentation pack <a class="header-anchor" href="#_1337-is-a-presentation-pack" aria-label="Permalink to “1337 is a presentation pack”">​</a></h3><p>GOAT 1337 is implemented as a trusted built-in <code>ExperiencePack</code> layered over the existing <code>ThemeSpec</code>. It can select:</p><ul><li>the 1337 colour and typography theme;</li><li>alternate Dock, About, and in-app icon assets;</li><li>chat-role glyphs and decorative emoji;</li><li>mascot sprite sheets and bounded interface animations;</li><li>optional completion sounds; and</li><li>alternate bylines, empty-state copy, labels, and other non-critical microcopy.</li></ul><p>The pack cannot alter engine requests, prompts, persisted message text, permissions, errors, destructive confirmations, database records, keyboard semantics, layout measurements, or feature availability. Decorations are derived at render time and never inserted into the transcript. Error and security copy always use the professional catalog.</p><p>Community GTF themes remain data-only and cannot provide executable behavior, sounds, copy catalogs, app icons, or arbitrary animation. Experience packs are trusted built-ins until a separate signed package decision exists.</p><h3 id="motion-assets-and-accessibility-stay-bounded" tabindex="-1">Motion, assets, and accessibility stay bounded <a class="header-anchor" href="#motion-assets-and-accessibility-stay-bounded" aria-label="Permalink to “Motion, assets, and accessibility stay bounded”">​</a></h3><p>Reduce Motion disables non-essential movement and replaces it with static 1337 art. Reduce Transparency and contrast requirements continue to apply through semantic tokens. VoiceOver labels describe the control or content, never its decorative goat.</p><p>Animation assets decode off-main, occupy a fixed final layout, pause when hidden or when the app is inactive, and allow at most one prominent looping mascot animation per window. Transcript rows do not run independent loops. Sprite sheets or frame sequences are preferred over multiple concurrently decoded GIFs. The performance budgets from ADR-0028 apply equally to the hidden pack.</p><p>The default and 1337 icon families are bundled and deterministic. Selecting an experience updates the runtime Dock icon where macOS permits it; packaging still has one canonical Finder icon and must remain correct if runtime icon replacement is unavailable.</p><h3 id="kid-scope" tabindex="-1">Kid scope <a class="header-anchor" href="#kid-scope" aria-label="Permalink to “Kid scope”">​</a></h3><p>This identity pivot ships in <strong>Kid 0.1.0 alongside M6 memory</strong>. It is companion release work, not part of the memory protocol. The Kid exit gate requires:</p><ol><li>a clean profile launches in professional System appearance;</li><li>1337 is absent from Appearance before unlock;</li><li>the About-scoped sequence unlocks locally and survives relaunch;</li><li>switching back to System restores professional icons, copy, and motion without altering content; and</li><li>Reduce Motion and the ADR-0028 rendering budgets hold in both experiences.</li></ol><p>M7 retains the broader command palette, onboarding, empty-state, and accessibility polish. It no longer owns the 1337 unlock.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2>`,18),c(`ul`,null,[l[14]||=c(`li`,null,`GOAT presents as a credible professional IDE on first launch while retaining a strong hidden personality for users who opt in.`,-1),l[15]||=c(`li`,null,[i(`Theme selection and experience selection become related but distinct concepts. `),c(`code`,null,`ThemeSpec`),i(` remains the public colour format; `),c(`code`,null,`ExperiencePack`),i(` coordinates trusted presentation assets.`)],-1),l[16]||=c(`li`,null,`Existing goat decorations and neon microcopy must move behind the 1337 gate or be removed from the default catalog.`,-1),l[17]||=c(`li`,null,`Every alternate string and asset needs a professional fallback. Screenshots, release notes, and onboarding use System unless they explicitly demonstrate the easter egg.`,-1),c(`li`,null,[l[12]||=i(`Kid gains a bounded presentation migration beside M6. `,-1),r(m,{term:`memory`},{default:n(()=>[...l[11]||=[i(`Memory`,-1)]]),_:1}),l[13]||=i(` sequencing remains unchanged.`,-1)])]),l[24]||=c(`h2`,{id:`alternatives-considered`,tabindex:`-1`},[i(`Alternatives considered `),c(`a`,{class:`header-anchor`,href:`#alternatives-considered`,"aria-label":`Permalink to “Alternatives considered”`},`​`)],-1),c(`p`,null,[l[19]||=i(`Keep the `,-1),r(m,{term:`goated`},{default:n(()=>[...l[18]||=[i(`GOATed`,-1)]]),_:1}),l[20]||=i(` look as the default (rejected: too loud for the primary professional audience), reduce 1337 to a colour theme (rejected: does not cover icons, emoji, motion, or copy), unlock through the command palette (rejected: makes Kid depend on M7 and turns an easter egg into a discoverable command), let community themes supply experience assets (rejected: expands security, performance, and packaging surface), and store decorated transcript text (rejected: presentation would corrupt user content and exports).`,-1)])])}var f=o(u,[[`render`,d]]);export{l as __pageData,f as default};